import { Component, input } from '@angular/core';
import { NzSkeletonModule } from 'ng-zorro-antd/skeleton';

/** hrm-skeleton — placeholder loading, bọc nz-skeleton. */
@Component({
  selector: 'hrm-skeleton',
  imports: [NzSkeletonModule],
  template: `
    <nz-skeleton
      [nzActive]="active()"
      [nzLoading]="loading()"
      [nzAvatar]="avatar()"
      [nzTitle]="title()"
      [nzParagraph]="{ rows: rows() }">
      <ng-content />
    </nz-skeleton>
  `,
  host: { class: 'hrm-skeleton' },
})
export class HrmSkeleton {
  readonly active = input(true);
  readonly loading = input(true);
  readonly avatar = input(false);
  readonly title = input(true);
  readonly rows = input(3);
}
